package main

import (
	"os"
	"strconv"
	"strings"
)

type Value struct {
	Number  float64
	Label   string
	Present bool
}
type Record map[string]Value
type DataFrame struct {
	Columns     []string
	Categorical map[string]bool
	Rows        []Record
}
type Params struct {
	Tolerance, Alpha, Confidence, Leverage, Studentized, Cook, DFFITS, VIF, DW, BP, Normal float64
	Best, Width, Height                                                                    int
	Limit                                                                                  float64
}

func readLines(path string) []string {
	data, e := os.ReadFile(path)
	if e != nil {
		panic(e)
	}
	return strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
}
func decimal(s string) float64 {
	v, e := strconv.ParseFloat(s, 64)
	if e != nil {
		panic(e)
	}
	return v
}
func readCSV(path string, kinds map[string]bool) DataFrame {
	lines := readLines(path)
	columns := strings.Split(lines[0], ",")
	records := [][]string{}
	for _, line := range lines[1:] {
		records = append(records, strings.Split(line, ","))
	}
	categories := map[string]bool{}
	for j, c := range columns {
		if kinds != nil {
			categories[c] = kinds[c]
		} else {
			for _, r := range records {
				v := r[j]
				if v != "NA" && v[0] >= 'A' && v[0] <= 'Z' {
					categories[c] = true
					break
				}
			}
		}
	}
	rows := []Record{}
	for _, r := range records {
		row := Record{}
		for j, c := range columns {
			v := r[j]
			item := Value{}
			if v != "NA" {
				item.Present = true
				if categories[c] {
					item.Label = v
				} else {
					item.Number = decimal(v)
				}
			}
			row[c] = item
		}
		rows = append(rows, row)
	}
	return DataFrame{columns, categories, rows}
}
func readParams() Params {
	v := map[string][]string{}
	for _, line := range readLines("input/params.txt") {
		f := strings.Split(line, " ")
		v[f[0]] = f[1:]
	}
	get := func(s string) float64 { return decimal(v[s][0]) }
	return Params{get("RANK_TOL"), get("ALPHA_REMOVE"), get("CONFIDENCE"), get("LEVERAGE"), get("STUDENTIZED"),
		get("COOK"), get("DFFITS"), get("VIF"), get("DURBIN_WATSON"), get("BREUSCH_PAGAN"), get("NORMALITY"),
		int(get("BEST_SUBSETS")), int(decimal(v["PLOT"][0])), int(decimal(v["PLOT"][1])), decimal(v["PLOT"][2])}
}

package main

import "math"

type RowDiagnostic struct {
	Standardized, Studentized, Cooks, DFFITS float64
	Flags                                    string
	DFBETAS                                  []float64
}
type Diagnostic struct {
	Rows                                     []RowDiagnostic
	DW, BP, BPP, JB, JBP, Skewness, Kurtosis float64
	BPDF                                     int
}

func calculateDiagnostics(f *Fit, p Params) Diagnostic {
	n, r := f.N, f.Rank
	df := n - r
	sigma := math.Sqrt(f.RSS / float64(df))
	leverageLimit := p.Leverage * float64(r) / float64(n)
	cookLimit := p.Cook / float64(n)
	dffitsLimit := p.DFFITS * math.Sqrt(float64(r)/float64(n))
	result := Diagnostic{}
	for i := 0; i < n; i++ {
		h, eps := f.Leverage[i], f.WeightedResidual[i]
		z := eps / (sigma * math.Sqrt(1-h))
		t := z * math.Sqrt(float64(df-1)/(float64(df)-z*z))
		cook := z * z * h / (float64(r) * (1 - h))
		dffits := t * math.Sqrt(h/(1-h))
		flags := ""
		if h > leverageLimit {
			flags += "H"
		}
		if math.Abs(t) > p.Studentized {
			flags += "O"
		}
		if cook > cookLimit {
			flags += "C"
		}
		if math.Abs(dffits) > dffitsLimit {
			flags += "F"
		}
		if flags == "" {
			flags = "-"
		}
		deleted := sigma * math.Sqrt((float64(df)-z*z)/float64(df-1))
		db := make([]float64, r)
		for k := range db {
			db[k] = f.G[i][k] * eps / (1 - h) / (deleted * math.Sqrt(f.Variance[k]))
		}
		result.Rows = append(result.Rows, RowDiagnostic{z, t, cook, dffits, flags, db})
	}
	numerator := 0.0
	for i := 1; i < n; i++ {
		d := f.WeightedResidual[i] - f.WeightedResidual[i-1]
		numerator += d * d
	}
	result.DW = numerator / f.RSS
	squared := make([]float64, n)
	ones := make([]float64, n)
	accepted := matrix(n, r)
	sum := 0.0
	for i, v := range f.WeightedResidual {
		squared[i] = v * v
		sum += squared[i]
		ones[i] = 1
		for k, j := range f.Accepted {
			accepted[i][k] = f.Matrix[i][j]
		}
	}
	aux := fit(accepted, squared, ones, p.Tolerance)
	mean := sum / float64(n)
	tss := 0.0
	for _, v := range squared {
		tss += (v - mean) * (v - mean)
	}
	result.BP = float64(n) * (1 - aux.RSS/tss)
	result.BPDF = aux.Rank - 1
	result.BPP = chiP(result.BP, result.BPDF)
	sum = 0
	for _, v := range f.WeightedResidual {
		sum += v
	}
	mean = sum / float64(n)
	m2, m3, m4 := 0.0, 0.0, 0.0
	for _, v := range f.WeightedResidual {
		d := v - mean
		m2 += d * d
		m3 += d * d * d
		m4 += d * d * d * d
	}
	m2 /= float64(n)
	m3 /= float64(n)
	m4 /= float64(n)
	result.Skewness = m3 / (m2 * math.Sqrt(m2))
	result.Kurtosis = m4 / (m2 * m2)
	s, k := result.Skewness, result.Kurtosis
	result.JB = float64(n) / 6 * (s*s + (k-3)*(k-3)/4)
	result.JBP = chiP(result.JB, 2)
	return result
}

package main

import (
	"math/bits"
	"sort"
	"strings"
)

type Factor struct {
	Name, Column string
	Power        int
	Categorical  bool
}

func parseFactor(name string) Factor {
	f := Factor{Name: name, Column: name, Power: 1}
	if strings.HasPrefix(name, "C(") {
		f.Categorical = true
		f.Column = name[2 : len(name)-1]
	} else if strings.HasPrefix(name, "I(") {
		parts := strings.Split(name[2:len(name)-1], "^")
		f.Column = parts[0]
		f.Power = int(parts[1][0] - '0')
	}
	return f
}
func (f Factor) value(row Record, level string) float64 {
	v := row[f.Column]
	if f.Categorical {
		if v.Label == level {
			return 1
		}
		return 0
	}
	x := v.Number
	if f.Power == 2 {
		return x * x
	}
	if f.Power == 3 {
		return x * x * x
	}
	return x
}

type Term struct {
	Name    string
	Factors []Factor
	Names   map[string]bool
}

func newTerm(factors []Factor) Term {
	names := []string{}
	set := map[string]bool{}
	for _, f := range factors {
		names = append(names, f.Name)
		set[f.Name] = true
	}
	return Term{strings.Join(names, ":"), factors, set}
}
func (t Term) contained(other Term) bool {
	if len(t.Names) >= len(other.Names) {
		return false
	}
	for f := range t.Names {
		if !other.Names[f] {
			return false
		}
	}
	return true
}

type Model struct {
	Original, Response, Weight                string
	Terms                                     []Term
	FactorColumns, CategoryColumns, Variables []string
}

func parseModel(line string) Model {
	split := strings.SplitN(line, " weights=", 2)
	m := Model{Original: split[0]}
	if len(split) == 2 {
		m.Weight = split[1]
	}
	parts := strings.Split(m.Original, " ~ ")
	m.Response = parts[0]
	seen := map[string]bool{}
	add := func(f []Factor) {
		term := newTerm(f)
		names := []string{}
		for n := range term.Names {
			names = append(names, n)
		}
		sort.Strings(names)
		key := strings.Join(names, "\x00")
		if !seen[key] {
			m.Terms = append(m.Terms, term)
			seen[key] = true
		}
	}
	for _, expression := range strings.Split(parts[1], " + ") {
		if strings.Contains(expression, "*") {
			names := strings.Split(expression, "*")
			factors := []Factor{}
			for _, n := range names {
				factors = append(factors, parseFactor(n))
			}
			for size := 1; size <= len(factors); size++ {
				for mask := 1; mask < 1<<len(factors); mask++ {
					if bits.OnesCount(uint(mask)) != size {
						continue
					}
					seq := []Factor{}
					for j, f := range factors {
						if mask&(1<<j) != 0 {
							seq = append(seq, f)
						}
					}
					add(seq)
				}
			}
		} else {
			factors := []Factor{}
			for _, name := range strings.Split(expression, ":") {
				factors = append(factors, parseFactor(name))
			}
			add(factors)
		}
	}
	cols, cats := map[string]bool{}, map[string]bool{}
	for _, t := range m.Terms {
		for _, f := range t.Factors {
			if !cols[f.Column] {
				m.FactorColumns = append(m.FactorColumns, f.Column)
				cols[f.Column] = true
			}
			if f.Categorical && !cats[f.Column] {
				m.CategoryColumns = append(m.CategoryColumns, f.Column)
				cats[f.Column] = true
			}
		}
	}
	m.Variables = append(append([]string{}, m.FactorColumns...), m.Response)
	if m.Weight != "" {
		m.Variables = append(m.Variables, m.Weight)
	}
	return m
}
func (m Model) format(terms []int) string {
	names := []string{}
	for _, i := range terms {
		names = append(names, m.Terms[i].Name)
	}
	rhs := "1"
	if len(names) > 0 {
		rhs = strings.Join(names, " + ")
	}
	return m.Response + " ~ " + rhs
}
func (m Model) removable(terms []int) []int {
	out := []int{}
	for _, i := range terms {
		ok := true
		for _, j := range terms {
			if m.Terms[i].contained(m.Terms[j]) {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, i)
		}
	}
	return out
}
func selectedTerms(terms []int) map[int]bool {
	set := map[int]bool{}
	for _, i := range terms {
		set[i] = true
	}
	return set
}
func (m Model) candidates(terms []int) []int {
	set := selectedTerms(terms)
	out := []int{}
	for i, t := range m.Terms {
		if set[i] {
			continue
		}
		ok := true
		for j, other := range m.Terms {
			if other.contained(t) && !set[j] {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, i)
		}
	}
	return out
}
func (m Model) hierarchical(terms []int) bool {
	set := selectedTerms(terms)
	for _, i := range terms {
		for j, t := range m.Terms {
			if t.contained(m.Terms[i]) && !set[j] {
				return false
			}
		}
	}
	return true
}

type Component struct {
	Factor      Factor
	Name, Level string
}
type DesignColumn struct {
	Term       int
	Name       string
	Components []Component
}

func (c DesignColumn) value(row Record) float64 {
	if len(c.Components) == 0 {
		return 1
	}
	v := c.Components[0].Factor.value(row, c.Components[0].Level)
	for _, s := range c.Components[1:] {
		v *= s.Factor.value(row, s.Level)
	}
	return v
}

type Design struct {
	Model             Model
	RowNumbers        []int
	Rows              []Record
	Levels            map[string][]string
	Columns           []DesignColumn
	Matrix            [][]float64
	Response, Weights []float64
}

func buildDesign(model Model, data DataFrame) *Design {
	d := &Design{Model: model, Levels: map[string][]string{}, Columns: []DesignColumn{{Term: -1, Name: "(Intercept)"}}}
	for i, row := range data.Rows {
		ok := true
		for _, c := range model.Variables {
			if !row[c].Present {
				ok = false
				break
			}
		}
		if ok {
			d.RowNumbers = append(d.RowNumbers, i+1)
			d.Rows = append(d.Rows, row)
		}
	}
	for _, c := range model.CategoryColumns {
		set := map[string]bool{}
		for _, r := range d.Rows {
			set[r[c].Label] = true
		}
		levels := []string{}
		for v := range set {
			levels = append(levels, v)
		}
		sort.Strings(levels)
		d.Levels[c] = levels
	}
	for i, t := range model.Terms {
		components := make([][]Component, len(t.Factors))
		for j, f := range t.Factors {
			if f.Categorical {
				for _, level := range d.Levels[f.Column][1:] {
					components[j] = append(components[j], Component{f, f.Name + level, level})
				}
			} else {
				components[j] = []Component{{Factor: f, Name: f.Name}}
			}
		}
		choices := make([]Component, len(components))
		var product func(int)
		product = func(j int) {
			if j < 0 {
				names := []string{}
				for _, c := range choices {
					names = append(names, c.Name)
				}
				d.Columns = append(d.Columns, DesignColumn{i, strings.Join(names, ":"), append([]Component{}, choices...)})
				return
			}
			for _, c := range components[j] {
				choices[j] = c
				product(j - 1)
			}
		}
		product(len(components) - 1)
	}
	for _, row := range d.Rows {
		d.Matrix = append(d.Matrix, d.values(row))
		d.Response = append(d.Response, row[model.Response].Number)
		w := 1.0
		if model.Weight != "" {
			w = row[model.Weight].Number
		}
		d.Weights = append(d.Weights, w)
	}
	return d
}
func (d *Design) values(row Record) []float64 {
	values := make([]float64, len(d.Columns))
	for j, c := range d.Columns {
		values[j] = c.value(row)
	}
	return values
}
func (d *Design) subsetMatrix(terms []int) [][]float64 {
	set := selectedTerms(terms)
	indices := []int{}
	for j, c := range d.Columns {
		if c.Term < 0 || set[c.Term] {
			indices = append(indices, j)
		}
	}
	out := make([][]float64, len(d.Rows))
	for i, row := range d.Matrix {
		for _, j := range indices {
			out[i] = append(out[i], row[j])
		}
	}
	return out
}
func (d *Design) predictable(row Record) bool {
	for _, c := range d.Model.FactorColumns {
		v := row[c]
		if !v.Present {
			return false
		}
		if levels, ok := d.Levels[c]; ok {
			found := false
			for _, s := range levels {
				if s == v.Label {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
	}
	return true
}

package main

import (
	"fmt"
	"math"
)

func logGamma(x float64) float64 {
	coefficients := []float64{76.18009172947146, -86.50532032941677, 24.01409824083091, -1.231739572450155, 0.001208650973866179, -0.000005395239384953}
	t := x + 5.5
	adjustment := t - (x+0.5)*math.Log(t)
	series := 1.000000000190015
	for j, c := range coefficients {
		series += c / (x + float64(j+1))
	}
	return -adjustment + math.Log(2.5066282746310005*series/x)
}
func replaceSmall(v float64) float64 {
	if math.Abs(v) < 1e-300 {
		return 1e-300
	}
	return v
}
func betaFraction(a, b, x float64) float64 {
	c := 1.0
	d := 1 / replaceSmall(1-(a+b)*x/(a+1))
	h := d
	for m := 1; m <= 1000; m++ {
		v := float64(m)
		q := v * (b - v) * x / ((a - 1 + 2*v) * (a + 2*v))
		d = 1 / replaceSmall(1+q*d)
		c = replaceSmall(1 + q/c)
		h *= d * c
		q = -(a + v) * (a + b + v) * x / ((a + 2*v) * (a + 1 + 2*v))
		d = 1 / replaceSmall(1+q*d)
		c = replaceSmall(1 + q/c)
		delta := d * c
		h *= delta
		if math.Abs(delta-1) < 1e-15 {
			break
		}
	}
	return h
}
func incompleteBeta(x, a, b float64) float64 {
	if x <= 0 {
		return 0
	}
	if x >= 1 {
		return 1
	}
	factor := math.Exp(logGamma(a+b) - logGamma(a) - logGamma(b) + a*math.Log(x) + b*math.Log(1-x))
	if x < (a+1)/(a+b+2) {
		return factor * betaFraction(a, b, x) / a
	}
	return 1 - factor*betaFraction(b, a, 1-x)/b
}
func upperGamma(a, x float64) float64 {
	if x <= 0 {
		return 1
	}
	factor := math.Exp(-x + a*math.Log(x) - logGamma(a))
	if x < a+1 {
		term, e := 1/a, a
		series := term
		for i := 0; i < 1000; i++ {
			e++
			term *= x / e
			series += term
			if math.Abs(term) < math.Abs(series)*1e-15 {
				break
			}
		}
		return 1 - series*factor
	}
	b := x + 1 - a
	c, d := 1/1e-300, 1/b
	h := d
	for i := 1; i <= 1000; i++ {
		q := -float64(i) * (float64(i) - a)
		b += 2
		d = 1 / replaceSmall(q*d+b)
		c = replaceSmall(b + q/c)
		delta := d * c
		h *= delta
		if math.Abs(delta-1) < 1e-15 {
			break
		}
	}
	return factor * h
}
func tP(t float64, df int) float64 { nu := float64(df); return incompleteBeta(nu/(nu+t*t), nu/2, 0.5) }
func fP(f float64, d1, d2 int) float64 {
	a, b := float64(d1), float64(d2)
	return incompleteBeta(b/(b+a*f), b/2, a/2)
}
func chiP(stat float64, df int) float64 { return upperGamma(float64(df)/2, stat/2) }
func tQuantile(confidence float64, df int) float64 {
	lo, hi := 0.0, 1000.0
	for i := 0; i < 100; i++ {
		mid := (lo + hi) / 2
		if tP(mid, df) > 1-confidence {
			lo = mid
		} else {
			hi = mid
		}
	}
	return (lo + hi) / 2
}
func significance(p float64) string {
	if math.IsNaN(p) {
		return ""
	}
	if p < 0.001 {
		return "***"
	}
	if p < 0.01 {
		return "**"
	}
	if p < 0.05 {
		return "*"
	}
	if p < 0.1 {
		return "."
	}
	return ""
}
func four(v float64) string {
	if math.IsNaN(v) {
		return "NA"
	}
	text := fmt.Sprintf("%.4f", v)
	if text == "-0.0000" {
		return "0.0000"
	}
	return text
}
func probability(v float64) string {
	if math.IsNaN(v) {
		return "NA"
	}
	if v < 0.0001 {
		return "<0.0001"
	}
	return four(v)
}

package main

import (
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Statistics struct {
	DF                                                                                  int
	Sigma, WeightSum, TSS, R2, Adjusted, F, P, LL, AIC, BIC, PRESS, Predicted, Critical float64
	Quantiles                                                                           []float64
}
type Coefficient struct{ Estimate, SE, T, P, Lower, Upper, RobustSE, RobustT, RobustP float64 }
type Anova struct {
	Index             int
	Name              string
	DF                int
	SS, MS, RSS, F, P float64
}
type VIFResult struct {
	Name  string
	Value float64
	High  bool
}
type ResetResult struct {
	F                   float64
	AddedDF, ResidualDF int
	P                   float64
}
type PredictionCheck struct {
	Predicted, Actual int
	RMSE              float64
	Covered           int
}
type Report struct {
	Number          int
	Design          *Design
	Fit             *Fit
	Stats           Statistics
	Coefficients    []Coefficient
	ANOVA, Marginal []Anova
	VIF             []VIFResult
	Diagnostic      Diagnostic
	Reset           ResetResult
	Predictions     []string
	Check           PredictionCheck
}

func text(v int) string { return strconv.Itoa(v) }
func table(header []string, rows [][]string, marks []string) []string {
	all := append([][]string{header}, rows...)
	widths := make([]int, len(header))
	for _, row := range all {
		for c, field := range row {
			widths[c] = max(widths[c], len(field))
		}
	}
	lines := []string{}
	for i, row := range all {
		line := row[0] + strings.Repeat(" ", widths[0]-len(row[0]))
		for c, field := range row[1:] {
			line += "  " + strings.Repeat(" ", widths[c+1]-len(field)) + field
		}
		if i > 0 && i-1 < len(marks) && marks[i-1] != "" {
			line += " " + marks[i-1]
		}
		lines = append(lines, strings.TrimRight(line, " "))
	}
	return lines
}
func orderedSum(values []float64) float64 {
	sum := 0.0
	for _, v := range values {
		sum += v
	}
	return sum
}
func informationCriteria(f *Fit) (float64, float64, float64) {
	logs := 0.0
	for _, w := range f.Weights {
		logs += math.Log(w)
	}
	n := float64(f.N)
	ll := 0.5 * (logs - n*(math.Log(2*math.Pi)+1-math.Log(n)+math.Log(f.RSS)))
	aic := -2*ll + 2*float64(f.Rank+1)
	bic := -2*ll + math.Log(n)*float64(f.Rank+1)
	return ll, aic, bic
}
func modelStatistics(f *Fit, confidence float64) Statistics {
	n, r := f.N, f.Rank
	df := n - r
	sumWeights := orderedSum(f.Weights)
	sumY := 0.0
	for i, y := range f.Response {
		sumY += f.Weights[i] * y
	}
	mean := sumY / sumWeights
	tss := 0.0
	for i, y := range f.Response {
		tss += f.Weights[i] * (y - mean) * (y - mean)
	}
	r2 := 1 - f.RSS/tss
	adjusted := 1 - (1-r2)*float64(n-1)/float64(df)
	stat := ((tss - f.RSS) / float64(r-1)) / (f.RSS / float64(df))
	ll, aic, bic := informationCriteria(f)
	press := 0.0
	for i, eps := range f.WeightedResidual {
		v := eps / (1 - f.Leverage[i])
		press += v * v
	}
	residuals := append([]float64{}, f.WeightedResidual...)
	sort.Float64s(residuals)
	quantiles := []float64{}
	for _, p := range []float64{0, 0.25, 0.5, 0.75, 1} {
		g := float64(n-1) * p
		k := int(math.Floor(g))
		q := residuals[k]
		if k+1 < n {
			q = q + (g-float64(k))*(residuals[k+1]-q)
		}
		quantiles = append(quantiles, q)
	}
	return Statistics{df, math.Sqrt(f.RSS / float64(df)), sumWeights, tss, r2, adjusted, stat, fP(stat,
		r-1, df), ll, aic, bic, press, 1 - press/tss, tQuantile(confidence, df), quantiles}
}
func coefficientInference(f *Fit, s Statistics) []Coefficient {
	omega := make([]float64, f.N)
	for i, eps := range f.WeightedResidual {
		omega[i] = eps * eps / ((1 - f.Leverage[i]) * (1 - f.Leverage[i]))
	}
	indices := map[int]int{}
	for k, j := range f.Accepted {
		indices[j] = k
	}
	out := []Coefficient{}
	for j, estimate := range f.Beta {
		if math.IsNaN(estimate) {
			v := math.NaN()
			out = append(out, Coefficient{v, v, v, v, v, v, v, v, v})
			continue
		}
		k := indices[j]
		se := s.Sigma * math.Sqrt(f.Variance[k])
		t := estimate / se
		half := s.Critical * se
		sum := 0.0
		for i := 0; i < f.N; i++ {
			sum += omega[i] * f.G[i][k] * f.G[i][k]
		}
		robust := math.Sqrt(sum)
		rt := estimate / robust
		out = append(out, Coefficient{estimate, se, t, tP(t, s.DF), estimate - half, estimate + half, robust, rt, tP(rt, s.DF)})
	}
	return out
}
func allTerms(model Model) []int {
	terms := make([]int, len(model.Terms))
	for i := range terms {
		terms[i] = i
	}
	return terms
}
func fitSubset(d *Design, terms []int, tolerance float64) *Fit {
	return fit(d.subsetMatrix(terms), d.Response, d.Weights, tolerance)
}
func removeTerm(terms []int, index int) []int {
	out := []int{}
	for _, i := range terms {
		if i != index {
			out = append(out, i)
		}
	}
	return out
}
func marginalTests(d *Design, f *Fit, terms []int, tolerance float64) []Anova {
	out := []Anova{}
	for _, i := range d.Model.removable(terms) {
		reduced := fitSubset(d, removeTerm(terms, i), tolerance)
		df := f.Rank - reduced.Rank
		ss := reduced.RSS - f.RSS
		stat, p := math.NaN(), math.NaN()
		if df > 0 {
			stat = (ss / float64(df)) / (f.RSS / float64(f.N-f.Rank))
			p = fP(stat, df, f.N-f.Rank)
		}
		out = append(out, Anova{Index: i, Name: d.Model.Terms[i].Name, DF: df, SS: ss, RSS: reduced.RSS, F: stat, P: p})
	}
	return out
}
func sequentialANOVA(d *Design, f *Fit) []Anova {
	out := []Anova{}
	for i, t := range d.Model.Terms {
		ss := 0.0
		df := 0
		for k, j := range f.Accepted {
			if d.Columns[j].Term == i {
				ss += f.Effects[k] * f.Effects[k]
				df++
			}
		}
		if df == 0 {
			continue
		}
		ms := ss / float64(df)
		stat := ms / (f.RSS / float64(f.N-f.Rank))
		out = append(out, Anova{Name: t.Name, DF: df, SS: ss, MS: ms, F: stat, P: fP(stat, df, f.N-f.Rank)})
	}
	return out
}
func varianceInflation(d *Design, f *Fit, s Statistics, p Params) []VIFResult {
	out := []VIFResult{}
	for _, column := range f.Accepted[1:] {
		response := make([]float64, f.N)
		x := make([][]float64, f.N)
		sum := 0.0
		for i, row := range f.Matrix {
			response[i] = row[column]
			sum += f.Weights[i] * response[i]
			for _, j := range f.Accepted {
				if j != column {
					x[i] = append(x[i], row[j])
				}
			}
		}
		aux := fit(x, response, f.Weights, p.Tolerance)
		mean := sum / s.WeightSum
		tss := 0.0
		for i, v := range response {
			tss += f.Weights[i] * (v - mean) * (v - mean)
		}
		r2 := 1 - aux.RSS/tss
		vif := 1 / (1 - r2)
		out = append(out, VIFResult{d.Columns[column].Name, vif, vif > p.VIF})
	}
	return out
}
func resetTest(f *Fit, tolerance float64) ResetResult {
	x := make([][]float64, f.N)
	for i, row := range f.Matrix {
		for _, j := range f.Accepted {
			x[i] = append(x[i], row[j])
		}
		v := f.Fitted[i]
		x[i] = append(x[i], v*v, v*v*v)
	}
	aug := fit(x, f.Response, f.Weights, tolerance)
	q, df := aug.Rank-f.Rank, f.N-aug.Rank
	stat := ((f.RSS - aug.RSS) / float64(q)) / (aug.RSS / float64(df))
	return ResetResult{stat, q, df, fP(stat, q, df)}
}
func predictionReport(number int, d *Design, f *Fit, s Statistics, data DataFrame) ([]string, PredictionCheck) {
	lines := []string{}
	check := PredictionCheck{RMSE: math.NaN()}
	squared := 0.0
	for i, row := range data.Rows {
		fields := []string{text(number), text(i + 1)}
		if !d.predictable(row) {
			for j := 0; j < 9; j++ {
				fields = append(fields, "NA")
			}
			lines = append(lines, strings.Join(fields, ","))
			continue
		}
		check.Predicted++
		values := d.values(row)
		predicted := 0.0
		for _, j := range f.Accepted {
			predicted += values[j] * f.Beta[j]
		}
		sum := 0.0
		for k := 0; k < f.Rank; k++ {
			u := 0.0
			for m, j := range f.Accepted {
				u += values[j] * f.Inverse[m][k]
			}
			sum += u * u
		}
		se := s.Sigma * math.Sqrt(sum)
		cw := s.Critical * se
		pw := s.Critical * math.Sqrt(s.Sigma*s.Sigma+se*se)
		lower, upper := predicted-pw, predicted+pw
		for _, v := range []float64{predicted, se, predicted - cw, predicted + cw, lower, upper} {
			fields = append(fields, four(v))
		}
		actual := row[d.Model.Response]
		if !actual.Present {
			fields = append(fields, "NA", "NA", "NA")
		} else {
			check.Actual++
			err := actual.Number - predicted
			squared += err * err
			covered := "no"
			if lower <= actual.Number && actual.Number <= upper {
				covered = "yes"
				check.Covered++
			}
			fields = append(fields, four(actual.Number), four(err), covered)
		}
		lines = append(lines, strings.Join(fields, ","))
	}
	if check.Actual > 0 {
		check.RMSE = math.Sqrt(squared / float64(check.Actual))
	}
	return lines, check
}
func analyzeModel(number int, d *Design, p Params, predict DataFrame) Report {
	f := fit(d.Matrix, d.Response, d.Weights, p.Tolerance)
	s := modelStatistics(f, p.Confidence)
	pred, check := predictionReport(number, d, f, s, predict)
	return Report{number, d, f, s, coefficientInference(f, s), sequentialANOVA(d, f), marginalTests(d,
		f, allTerms(d.Model), p.Tolerance), varianceInflation(d, f, s, p), calculateDiagnostics(f,
		p), resetTest(f, p.Tolerance), pred, check}
}
func dataSummary(data DataFrame) []string {
	numeric := []string{}
	rows := [][]string{}
	for _, c := range data.Columns {
		if data.Categorical[c] {
			continue
		}
		numeric = append(numeric, c)
		values := []float64{}
		for _, row := range data.Rows {
			if v := row[c]; v.Present {
				values = append(values, v.Number)
			}
		}
		n := len(values)
		mean := orderedSum(values) / float64(n)
		sum := 0.0
		lo, hi := values[0], values[0]
		for _, v := range values {
			sum += (v - mean) * (v - mean)
			lo = math.Min(lo, v)
			hi = math.Max(hi, v)
		}
		rows = append(rows, []string{c, text(n), text(len(data.Rows) - n), four(mean), four(math.Sqrt(sum / float64(n-1))), four(lo), four(hi)})
	}
	lines := []string{fmt.Sprintf("Data: %d rows, %d columns", len(data.Rows), len(data.Columns)), "", "Numeric columns:"}
	lines = append(lines, table([]string{"column", "n", "missing", "Mean", "SD", "Min", "Max"}, rows, nil)...)
	lines = append(lines, "", "Categorical columns:")
	for _, c := range data.Columns {
		if !data.Categorical[c] {
			continue
		}
		counts := map[string]int{}
		present := 0
		for _, row := range data.Rows {
			if v := row[c]; v.Present {
				present++
				counts[v.Label]++
			}
		}
		levels := []string{}
		for label := range counts {
			levels = append(levels, label)
		}
		sort.Strings(levels)
		fields := []string{}
		for _, label := range levels {
			fields = append(fields, label+" "+text(counts[label]))
		}
		lines = append(lines, fmt.Sprintf("%s: %d values, %d missing, %d levels: %s", c, present, len(data.Rows)-present, len(levels), strings.Join(fields, ", ")))
	}
	lines = append(lines, "", "Correlations (pairwise complete observations):")
	rows = [][]string{}
	for _, a := range numeric {
		fields := []string{a}
		for _, b := range numeric {
			pairs := [][2]float64{}
			sx, sy := 0.0, 0.0
			for _, row := range data.Rows {
				x, y := row[a], row[b]
				if x.Present && y.Present {
					pairs = append(pairs, [2]float64{x.Number, y.Number})
					sx += x.Number
					sy += y.Number
				}
			}
			mx, my := sx/float64(len(pairs)), sy/float64(len(pairs))
			cross, xx, yy := 0.0, 0.0, 0.0
			for _, pair := range pairs {
				x, y := pair[0]-mx, pair[1]-my
				cross += x * y
				xx += x * x
				yy += y * y
			}
			fields = append(fields, four(cross/math.Sqrt(xx*yy)))
		}
		rows = append(rows, fields)
	}
	header := append([]string{"column"}, numeric...)
	lines = append(lines, table(header, rows, nil)...)
	return append(lines, "")
}
func coefficientTables(r Report, confidence float64) ([]string, []string, []string) {
	ordinary, intervals, robust := [][]string{}, [][]string{}, [][]string{}
	marks, robustMarks := []string{}, []string{}
	for j, c := range r.Coefficients {
		name := r.Design.Columns[j].Name
		ordinary = append(ordinary, []string{name, four(c.Estimate), four(c.SE), four(c.T), probability(c.P)})
		intervals = append(intervals, []string{name, four(c.Lower), four(c.Upper)})
		robust = append(robust, []string{name, four(c.RobustSE), four(c.RobustT), probability(c.RobustP)})
		marks = append(marks, significance(c.P))
		robustMarks = append(robustMarks, significance(c.RobustP))
	}
	ci := []string{fmt.Sprintf("Confidence intervals (level %s, t %s):", four(confidence), four(r.Stats.Critical))}
	ci = append(ci, table([]string{"term", "Lower", "Upper"}, intervals, nil)...)
	return table([]string{"term", "Estimate", "Std. Error", "t value", "Pr(>|t|)"}, ordinary, marks),
		ci, table([]string{"term", "Std. Error", "t value", "Pr(>|t|)"}, robust, robustMarks)
}
func anovaTables(r Report) ([]string, []string) {
	rows, marks := [][]string{}, []string{}
	for _, t := range r.ANOVA {
		rows = append(rows, []string{t.Name, text(t.DF), four(t.SS), four(t.MS), four(t.F), probability(t.P)})
		marks = append(marks, significance(t.P))
	}
	rows = append(rows, []string{"Residuals", text(r.Stats.DF), four(r.Fit.RSS), four(r.Fit.RSS / float64(r.Stats.DF))})
	marks = append(marks, "")
	seq := table([]string{"term", "Df", "Sum Sq", "Mean Sq", "F value", "Pr(>F)"}, rows, marks)
	rows, marks = [][]string{}, []string{}
	for _, t := range r.Marginal {
		rows = append(rows, []string{t.Name, text(t.DF), four(t.SS), four(t.RSS), four(t.F), probability(t.P)})
		marks = append(marks, significance(t.P))
	}
	return seq, table([]string{"term", "Df", "Sum Sq", "RSS", "F value", "Pr(>F)"}, rows, marks)
}
func diagnosticSummary(r Report, p Params) []string {
	f, d, design := r.Fit, r.Diagnostic, r.Design
	dwLabel := "no autocorrelation"
	if d.DW < p.DW {
		dwLabel = "positive autocorrelation"
	} else if d.DW > 4-p.DW {
		dwLabel = "negative autocorrelation"
	}
	bpLabel := "homoscedastic"
	if d.BPP < p.BP {
		bpLabel = "heteroscedastic"
	}
	jbLabel := "normal"
	if d.JBP < p.Normal {
		jbLabel = "non-normal"
	}
	outlier := 0
	counts := map[byte]int{}
	any := 0
	order := make([]int, f.N)
	for i, row := range d.Rows {
		order[i] = i
		if math.Abs(row.Studentized) > math.Abs(d.Rows[outlier].Studentized) {
			outlier = i
		}
		if row.Flags != "-" {
			any++
			for j := 0; j < len(row.Flags); j++ {
				counts[row.Flags[j]]++
			}
		}
	}
	unadjusted := tP(d.Rows[outlier].Studentized, f.N-f.Rank-1)
	bonferroni := math.Min(1, float64(f.N)*unadjusted)
	sort.SliceStable(order, func(i, j int) bool { return d.Rows[order[i]].Cooks > d.Rows[order[j]].Cooks })
	reset := r.Reset
	lines := []string{"Diagnostics:", fmt.Sprintf("Durbin-Watson: %s (%s)", four(d.DW), dwLabel), fmt.Sprintf("Breusch-Pagan: %s on %d DF, p-value: %s (%s)",
		four(d.BP), d.BPDF, probability(d.BPP), bpLabel), fmt.Sprintf("Jarque-Bera: %s on 2 DF, p-value: %s, skewness %s, kurtosis %s (%s)",
		four(d.JB), probability(d.JBP), four(d.Skewness), four(d.Kurtosis), jbLabel), fmt.Sprintf("RESET (powers 2 and 3): F %s on %d and %d DF, p-value: %s",
		four(reset.F), reset.AddedDF, reset.ResidualDF, probability(reset.P)), fmt.Sprintf("Outlier test: row %d, studentized %s, unadjusted p-value: %s, Bonferroni p-value: %s",
		design.RowNumbers[outlier], four(d.Rows[outlier].Studentized), probability(unadjusted), probability(bonferroni)),
		fmt.Sprintf("Flagged rows: leverage %d, outlier %d, cooks %d, dffits %d, any %d", counts['H'],
			counts['O'], counts['C'], counts['F'], any), "Largest Cook's distances:"}
	for _, i := range order[:min(3, f.N)] {
		row := d.Rows[i]
		lines = append(lines, fmt.Sprintf("row %d: cooks_d %s, leverage %s, studentized %s, flags %s", design.RowNumbers[i],
			four(row.Cooks), four(f.Leverage[i]), four(row.Studentized), row.Flags))
	}
	lines = append(lines, "Largest absolute DFBETAS:")
	rows := [][]string{}
	for k, column := range f.Accepted {
		best := 0
		for i := 1; i < f.N; i++ {
			if math.Abs(d.Rows[i].DFBETAS[k]) > math.Abs(d.Rows[best].DFBETAS[k]) {
				best = i
			}
		}
		rows = append(rows, []string{design.Columns[column].Name, text(design.RowNumbers[best]), four(d.Rows[best].DFBETAS[k])})
	}
	return append(lines, table([]string{"column", "row", "DFBETAS"}, rows, nil)...)
}
func modelSummary(r Report, total int, p Params) []string {
	d, f, s := r.Design, r.Fit, r.Stats
	aliases := []string{}
	for _, j := range f.Aliases {
		aliases = append(aliases, d.Columns[j].Name)
	}
	aliasText := "none"
	if len(aliases) > 0 {
		aliasText = strings.Join(aliases, ", ")
	}
	terms := []string{}
	for _, t := range d.Model.Terms {
		terms = append(terms, t.Name)
	}
	weight := d.Model.Weight
	if weight == "" {
		weight = "none"
	}
	q := s.Quantiles
	coef, intervals, robust := coefficientTables(r, p.Confidence)
	seq, marginal := anovaTables(r)
	lines := []string{fmt.Sprintf("Model %d: %s", r.Number, d.Model.Original), "Terms: " + strings.Join(terms,
		", "), "Weights: " + weight, fmt.Sprintf("Observations: %d used, %d dropped", f.N, total-f.N),
		fmt.Sprintf("Columns: %d, rank %d, aliased: %s", f.P, f.Rank, aliasText), "", fmt.Sprintf("Residuals: Min %s, 1Q %s, Median %s, 3Q %s, Max %s",
			four(q[0]), four(q[1]), four(q[2]), four(q[3]), four(q[4])), "", "Coefficients:"}
	lines = append(lines, coef...)
	lines = append(lines, "---", "Signif. codes: 0 '***' 0.001 '**' 0.01 '*' 0.05 '.' 0.1 ' ' 1", "",
		fmt.Sprintf("Residual standard error: %s on %d degrees of freedom", four(s.Sigma), s.DF),
		fmt.Sprintf("Multiple R-squared: %s, Adjusted R-squared: %s", four(s.R2), four(s.Adjusted)),
		fmt.Sprintf("F-statistic: %s on %d and %d DF, p-value: %s", four(s.F), f.Rank-1, s.DF, probability(s.P)),
		fmt.Sprintf("Log-likelihood: %s, AIC: %s, BIC: %s", four(s.LL), four(s.AIC), four(s.BIC)),
		fmt.Sprintf("PRESS: %s, Predicted R-squared: %s", four(s.PRESS), four(s.Predicted)), "")
	lines = append(lines, intervals...)
	lines = append(lines, "", "Robust standard errors (HC3):")
	lines = append(lines, robust...)
	lines = append(lines, "", "Analysis of variance (sequential):")
	lines = append(lines, seq...)
	lines = append(lines, "", "Marginal F tests (drop one term):")
	lines = append(lines, marginal...)
	lines = append(lines, "", "Variance inflation factors:")
	rows, marks := [][]string{}, []string{}
	for _, v := range r.VIF {
		rows = append(rows, []string{v.Name, four(v.Value)})
		mark := ""
		if v.High {
			mark = "high"
		}
		marks = append(marks, mark)
	}
	lines = append(lines, table([]string{"column", "VIF"}, rows, marks)...)
	lines = append(lines, "")
	return append(lines, diagnosticSummary(r, p)...)
}
